import React, { useRef, useState, useEffect, useLayoutEffect, useCallback, useMemo } from "react"
import * as am4core from "@amcharts/amcharts4/core"
import * as am4charts from "@amcharts/amcharts4/charts"
import { makeStyles } from "@material-ui/core/styles"
import Button from "@material-ui/core/Button"
import Box from "@material-ui/core/Box"
import Typography from "@material-ui/core/Typography"
import Networking from "../../networking"
import { EN_factors, LL2NE } from "../../shared/utilities"
import { GNSS_FIX_TYPE } from "../../shared/constants"

// Non-material-ui CSS, used to maintain the chart's aspect ratio
// This trick works because the percentage of paddingTop refers to the width of the parent element
const chartContainer = {
  // make sure the min function is the same for both width and paddingTop
  width: "calc(min(100%, 70vh))",
  paddingTop: "calc((min(100%, 70vh)) - 0px)",
  position: "relative",
} as React.CSSProperties

const chartStyle = {
  top: 0,
  left: 0,
  bottom: 0,
  right: 0,
  position: "absolute",
} as React.CSSProperties

class PathDisplay {
  latitudes: number[] //robot path latitudes
  longitudes: number[] //robot path longitudes
  easts: number[] // array of East values for robot
  norths: number[] // array of North values for robot
  vehicle_path_latitudes: number[] // vehicle path latitudes
  vehicle_path_longitudes: number[] // vehicle path longitudes
  vehicle_easts: number[] // array of East values for vehicle
  vehicle_norths: number[] // array of North values for vehicles

  E_factor: number
  N_factor: number
  lat_ref: number // latitude reference
  long_ref: number //longitude reference
  robot_east: number
  robot_north: number

  last_plotted_robot_east: number
  last_plotted_robot_north: number
  last_plotted_robot_heading: number

  last_plotted_vehicle_east: number;
  last_plotted_vehicle_north: number;
  last_plotted_vehicle_heading: number;

  constructor() {
    this.latitudes = []
    this.longitudes = []
    this.easts = []
    this.norths = []
    this.vehicle_path_latitudes = []
    this.vehicle_path_longitudes = []
    this.vehicle_easts = []
    this.vehicle_norths = []
    this.E_factor = 0
    this.N_factor = 0
    this.lat_ref = 0
    this.long_ref = 0
    this.robot_east = 0
    this.robot_north = 0

    // Last_plotted values
    this.last_plotted_robot_east = 0
    this.last_plotted_robot_north = 0
    this.last_plotted_robot_heading = 0
    this.last_plotted_vehicle_east = 0
    this.last_plotted_vehicle_north = 0
    this.last_plotted_vehicle_heading = 0
  }

  // Robot Path 
  plotPathSeries(
    latitudes: number[],
    longitudes: number[],
    pathSeriesRef: React.MutableRefObject<any>,
    forceRun: boolean
  ) {
    // Update if forceRun is true or the path data has changed
    if (forceRun === true || (JSON.stringify(this.latitudes) !== JSON.stringify(latitudes) && pathSeriesRef.current !== undefined)) {
      this.latitudes = [...latitudes]
      this.longitudes = [...longitudes]

      this.easts = []
      this.norths = []

      if (latitudes.length === 0) {  // Reset refs if the path is empty
        if (pathSeriesRef.current) 
          pathSeriesRef.current.data = []
        if (latitudes.length === 0 && (this.lat_ref !== 0 && this.long_ref !== 0) &&
            (Math.abs(this.lat_ref - this.latitudes[0]) < 1e-7 && Math.abs(this.long_ref - this.longitudes[0]) < 1e-7) ) {
            this.lat_ref = 0
            this.long_ref = 0
            this.E_factor = 0
            this.N_factor = 0
        }
        return
      }

      // Update lat_ref/long_ref if it's 0 or the path's starting point has changed.
      if (this.lat_ref === 0 || this.long_ref === 0 ||
          Math.abs(latitudes[0] - this.lat_ref) > 1e-7 ||
          Math.abs(longitudes[0] - this.long_ref) > 1e-7) {

          const [E_factor, N_factor] = EN_factors(latitudes[0])
          this.E_factor = E_factor
          this.N_factor = N_factor
          this.lat_ref = latitudes[0]
          this.long_ref = longitudes[0]
      }

      for (let i = 0; i < latitudes.length; i++) {
        const [pos_north, pos_east] = LL2NE(
          latitudes[i],
          longitudes[i],
          this.lat_ref,
          this.long_ref,
          this.E_factor,
          this.N_factor
        )
        this.easts.push(pos_east)
        this.norths.push(pos_north)
      }
      if (pathSeriesRef.current) pathSeriesRef.current.data = this.createPathSeriesData()
    }
  }

  createPathSeriesData() {
    const pathSeriesData = []
    for (let i = 0; i < this.easts.length; i++) {
      pathSeriesData.push({ ax: this.easts[i], ay: this.norths[i], aValue: i })
    }
    return pathSeriesData
  }

  // Robot position
  plotRobotSeries(
    latitude: number,
    longitude: number,
    headingRadian: number,
    robotSeriesRef: React.MutableRefObject<any>,
    forceUpdate: boolean = false
  ) {
    if (robotSeriesRef.current === undefined) 
      return;

    const isCurrentGpsInvalid = (latitude === 0 && longitude === 0);  // If current GPS data is invalid (0,0)

    // Try to establish lat_ref if it's 0 and VALID GPS data is available.
    if (this.lat_ref === 0 && !isCurrentGpsInvalid) {
      const [E_factor, N_factor] = EN_factors(latitude);
      this.E_factor = E_factor;
      this.N_factor = N_factor;
      this.lat_ref = latitude;
      this.long_ref = longitude;
    }

    // Make sure lat_ref and current GPS data are valid before plotting
    if (this.lat_ref !== 0 && !isCurrentGpsInvalid) {
      const [pos_north, pos_east] = LL2NE(
        latitude,
        longitude,
        this.lat_ref,
        this.long_ref,
        this.E_factor,
        this.N_factor
      );

      const currentHeadingDeg = (headingRadian / Math.PI) * 180;

      let shouldPlotBasedOnThreshold = false;
      const deltaEast = pos_east - this.last_plotted_robot_east;
      const deltaNorth = pos_north - this.last_plotted_robot_north;
      const distanceMoved = Math.sqrt(deltaEast * deltaEast + deltaNorth * deltaNorth);
      const deltaHeading = Math.abs(currentHeadingDeg - this.last_plotted_robot_heading);

      const POSITION_THRESHOLD_METERS = 0.1; // If lat/long changes by >= 0.1m, then update robot location
      const HEADING_THRESHOLD_DEGREES = 3; // If heading changes by >= 3 degrees, then update robot location

      if (forceUpdate) { 
          shouldPlotBasedOnThreshold = true;
      } else {
          if (distanceMoved > POSITION_THRESHOLD_METERS) {
              shouldPlotBasedOnThreshold = true;
          } else if (deltaHeading > HEADING_THRESHOLD_DEGREES) {
              shouldPlotBasedOnThreshold = true;
          }
      }

      if (shouldPlotBasedOnThreshold) { // update if position threshold is different enough from current values.
        robotSeriesRef.current.data = [{ bx: pos_east, by: pos_north, angle: currentHeadingDeg }];
        this.last_plotted_robot_east = pos_east;
        this.last_plotted_robot_north = pos_north;
        this.last_plotted_robot_heading = currentHeadingDeg;
      }

      // Always update for display purposes (numerical values below chart)
      this.robot_east = pos_east;
      this.robot_north = pos_north;

    } else {
        // If lat_ref is 0 or GPS is invalid (0,0), clear robot chart data
        robotSeriesRef.current.data = [];
        this.robot_east = 0;
        this.robot_north = 0;
        this.last_plotted_robot_east = 0;
        this.last_plotted_robot_north = 0;
        this.last_plotted_robot_heading = 0;
    }
  }

  // Vehicle Path
  plotVehiclePathSeries(
    latitudes: number[],
    longitudes: number[],
    vehiclePathSeriesRef: React.MutableRefObject<any>,
    forceRun: boolean
  ) {
    if (vehiclePathSeriesRef.current === undefined) 
      return;

    if (forceRun === true || (JSON.stringify(this.vehicle_path_latitudes) !== JSON.stringify(latitudes))) {
      this.vehicle_path_latitudes = [...latitudes]
      this.vehicle_path_longitudes = [...longitudes]

      this.vehicle_easts = []
      this.vehicle_norths = []

      if (latitudes.length === 0) {
        vehiclePathSeriesRef.current.data = []
        return
      }

      // Vehicle path can only be plotted if robot's lat_ref is established
      if (this.lat_ref === 0) {
          console.warn("Reference point for plotting (robot path) not yet set. Cannot convert vehicle path data.")
          vehiclePathSeriesRef.current.data = []
          return
      }

      for (let i = 0; i < latitudes.length; i++) {
        const [pos_north, pos_east] = LL2NE(
          latitudes[i],
          longitudes[i],
          this.lat_ref,
          this.long_ref,
          this.E_factor,
          this.N_factor
        )
        this.vehicle_easts.push(pos_east)
        this.vehicle_norths.push(pos_north)
      }

      vehiclePathSeriesRef.current.data = this.createVehiclePathSeriesData()
    }
  }

  createVehiclePathSeriesData() {
    const vehiclePathSeriesData = []
    for (let i = 0; i < this.vehicle_easts.length; i++) {
      vehiclePathSeriesData.push({ cx: this.vehicle_easts[i], cy: this.vehicle_norths[i], cValue: i })
    }
    return vehiclePathSeriesData
  }

  // Vehicle Location
  plotVehiclePositionSeries(
    latitude: number,
    longitude: number,
    headingDeg: number,
    vehiclePositionSeriesRef: React.MutableRefObject<any>,
    forceUpdate: boolean = false
  ) {
    if (vehiclePositionSeriesRef.current === undefined) 
      return;

    // Condition 1: If current GPS data is invalid (0,0)
    const isCurrentGpsInvalid = (latitude === 0 && longitude === 0);

    // Plot only when lat_ref is established and vehicle GPS data is valid.
    if (this.lat_ref === 0 || isCurrentGpsInvalid) {
        vehiclePositionSeriesRef.current.data = [];
        this.last_plotted_vehicle_east = 0;
        this.last_plotted_vehicle_north = 0;
        this.last_plotted_vehicle_heading = 0;
        return;
    }

    const [pos_north, pos_east] = LL2NE(
      latitude,
      longitude,
      this.lat_ref,
      this.long_ref,
      this.E_factor,
      this.N_factor
    )

    let shouldPlotBasedOnThreshold = false;

    const deltaEast = pos_east - this.last_plotted_vehicle_east;
    const deltaNorth = pos_north - this.last_plotted_vehicle_north;
    const distanceMoved = Math.sqrt(deltaEast * deltaEast + deltaNorth * deltaNorth);
    const deltaHeading = Math.abs(headingDeg - this.last_plotted_vehicle_heading);

    const POSITION_THRESHOLD_METERS = 0.1; // If lat/long changes by >= 0.1m, then update vehicle location
    const HEADING_THRESHOLD_DEGREES = 3; // If heading changes by >= 3 degrees, then update vehicle location

    if (forceUpdate) {
        shouldPlotBasedOnThreshold = true;
    } else {
        if (distanceMoved > POSITION_THRESHOLD_METERS) {
            shouldPlotBasedOnThreshold = true;
        } else if (deltaHeading > HEADING_THRESHOLD_DEGREES) {
            shouldPlotBasedOnThreshold = true;
        }
    }

    if (shouldPlotBasedOnThreshold) { // Only update chart data if position has changed by threshold amount
      vehiclePositionSeriesRef.current.data = [{ dx: pos_east, dy: pos_north, veh_angle: headingDeg }];

      // Update last plotted values when an update occurs
      this.last_plotted_vehicle_east = pos_east;
      this.last_plotted_vehicle_north = pos_north;
      this.last_plotted_vehicle_heading = headingDeg;
    }
  }
}

const useStyles = makeStyles((theme) => ({
  notes: {
    margin: theme.spacing(1),
  },
  body: {
    margin: theme.spacing(1),
  },
  button: {
    margin: theme.spacing(0.5),
    padding: theme.spacing(1),
    fontSize: 11,
  },
  messageBox: {
    maxHeight: 10,
  },
  stopManualRecording: { //Diffent button color while manual reocrding ongoing
    marginLeft: theme.spacing(0.5),
    backgroundColor: 'red',
    color: 'white',
    '&:hover': {backgroundColor: 'crimson',}
  },
}))

interface Props {
  networking: Networking
}

export default function Component({ networking }: Props) {
  const classes = useStyles()
  const [isManualRecording, setIsManualRecording] = useState(false)
  const [isVehiclePathVisible, setIsVehiclePathVisible] = useState(false)

  // Ref for PathDisplay instance
  const pathDisplayRef = useRef<PathDisplay | null>(null);

  // Initialize PathDisplay instance once on the first render (or after component mount)
  useLayoutEffect(() => {
    if (pathDisplayRef.current === null) {
      pathDisplayRef.current = new PathDisplay();
    }
  }, []); // Empty dependency array ensures this runs once for component mount.

  const vehicleArrowRef = useRef<am4core.Triangle | undefined>()

  const downloadTestData = () => {
    const link = document.createElement("a")
    link.href = `http://195.0.0.${networking.guiState.id}:3001/test-data.csv`
    link.click()
  }

  const handleStartManualRecording = () => {
    networking.senders.manual_recording_status(true);
    setIsManualRecording(true);
  }

  const handleStopManualRecording = () => {
    networking.senders.manual_recording_status(false);
    setIsManualRecording(false);
  }

  const pathSeriesRef: React.MutableRefObject<any> = useRef()
  const robotSeriesRef: React.MutableRefObject<any> = useRef()
  const vehiclePathSeriesRef: React.MutableRefObject<any> = useRef()
  const vehiclePositionSeriesRef: React.MutableRefObject<any> = useRef()
  const xAxisRef: React.MutableRefObject<any> = useRef()
  const yAxisRef: React.MutableRefObject<any> = useRef()
  const chartRef: React.MutableRefObject<any> = useRef()

  // Store lat/long for comparing contents 
  const robotPathLatitudesStr = useMemo(() => networking.pathToFollow.latitudes.join(','), [networking.pathToFollow.latitudes]);
  const robotPathLongitudesStr = useMemo(() => networking.pathToFollow.longitudes.join(','), [networking.pathToFollow.longitudes]);
  const vehiclePathLatitudesStr = useMemo(() => networking.vehiclePathToFollow.latitudes.join(','), [networking.vehiclePathToFollow.latitudes]);
  const vehiclePathLongitudesStr = useMemo(() => networking.vehiclePathToFollow.longitudes.join(','), [networking.vehiclePathToFollow.longitudes]);

  const updateChartZoom = useCallback(() => {
    const currentPathDisplay = pathDisplayRef.current;
    if (!currentPathDisplay) return;

    const allEasts = [...currentPathDisplay.easts]
    const allNorths = [...currentPathDisplay.norths]

    if (isVehiclePathVisible) {
      allEasts.push(...currentPathDisplay.vehicle_easts)
      allNorths.push(...currentPathDisplay.vehicle_norths)
    }

    if (allEasts.length <= 1 || allNorths.length <= 1) { // Default zoom for <1 point
      if (xAxisRef.current && yAxisRef.current) {
        xAxisRef.current.min = -5
        xAxisRef.current.max = 5
        yAxisRef.current.min = -5
        yAxisRef.current.max = 5
        chartRef.current?.validateData()
        chartRef.current?.validateLayout()
      }
      return
    }

    const eastMin = Math.min(...allEasts)
    const eastMax = Math.max(...allEasts)
    const northMin = Math.min(...allNorths)
    const northMax = Math.max(...allNorths)

    const padding = 3
    let effectiveEastMin = eastMin - padding
    let effectiveEastMax = eastMax + padding
    let effectiveNorthMin = northMin - padding
    let effectiveNorthMax = northMax + padding

    const minSpan = 10 // Minimum zoom level
    const currentEastSpan = effectiveEastMax - effectiveEastMin
    const currentNorthSpan = effectiveNorthMax - effectiveNorthMin

    if (currentEastSpan < minSpan) {
      const center = (effectiveEastMin + effectiveEastMax) / 2
      effectiveEastMin = center - minSpan / 2
      effectiveEastMax = center + minSpan / 2
    }
    if (currentNorthSpan < minSpan) {
      const center = (effectiveNorthMin + effectiveNorthMax) / 2
      effectiveNorthMin = center - minSpan / 2
      effectiveNorthMax = center + minSpan / 2
    }

    if (xAxisRef.current && yAxisRef.current) {
        // Use a 0ms timeout to defer axis updates slightly, allowing chart to process data first.
        setTimeout(() => {
            xAxisRef.current.min = effectiveEastMin
            xAxisRef.current.max = effectiveEastMax
            yAxisRef.current.min = effectiveNorthMin
            yAxisRef.current.max = effectiveNorthMax

            chartRef.current?.validateData()
            chartRef.current?.validateLayout()
        }, 0)
    }
  }, [
    isVehiclePathVisible,
    pathDisplayRef,
    xAxisRef, yAxisRef, chartRef
  ])

  const toggleVehiclePathVisibility = useCallback(() => {
    setIsVehiclePathVisible((prevState) => {
      const newVisibility = !prevState;
      const currentPathDisplay = pathDisplayRef.current;
      if (!currentPathDisplay) return newVisibility;

      // Update visibility of vehicle path/location
      if (vehiclePathSeriesRef.current) {
        vehiclePathSeriesRef.current.hidden = !newVisibility; // hidden
      }
      if (vehicleArrowRef.current) {
        vehicleArrowRef.current.visible = newVisibility; // visible
      }

      // Re-plot robot position and vehicle position with forceUpdate.
      currentPathDisplay.plotRobotSeries(
        networking.robotState.gps.latitude,
        networking.robotState.gps.longitude,
        networking.robotState.gps.heading,
        robotSeriesRef,
        true // forceUpdate = true
      );

      currentPathDisplay.plotVehiclePositionSeries(
        networking.robotState.targetVehicle.latitude,
        networking.robotState.targetVehicle.longitude,
        networking.robotState.targetVehicle.heading,
        vehiclePositionSeriesRef,
        true // forceUpdate = true
      );

      updateChartZoom();

      return newVisibility;
    });
  }, [
    updateChartZoom,
    robotSeriesRef,
    vehiclePositionSeriesRef,
    vehiclePathSeriesRef,
    vehicleArrowRef,
    pathDisplayRef,
    networking
  ]);

  // Continuously update robot and vehicle positions based on networking data
  useEffect(() => {
    const currentPathDisplay = pathDisplayRef.current;
    if (!currentPathDisplay) return;

    currentPathDisplay.plotRobotSeries(
      networking.robotState.gps.latitude,
      networking.robotState.gps.longitude,
      networking.robotState.gps.heading,
      robotSeriesRef
    );

    currentPathDisplay.plotVehiclePositionSeries(
      networking.robotState.targetVehicle.latitude,
      networking.robotState.targetVehicle.longitude,
      networking.robotState.targetVehicle.heading,
      vehiclePositionSeriesRef
    );

  }, [
    networking.robotState.gps.latitude,
    networking.robotState.gps.longitude,
    networking.robotState.gps.heading,
    networking.robotState.targetVehicle.latitude,
    networking.robotState.targetVehicle.longitude,
    networking.robotState.targetVehicle.heading,
    robotSeriesRef,
    vehiclePositionSeriesRef,
    pathDisplayRef,
  ]);


  // Chart creation and initial data plotting
  useLayoutEffect(() => {
    if (chartRef.current) {
      chartRef.current.dispose()
    }

    // Create new chart instance
    let chart = am4core.create("chartdiv", am4charts.XYChart)
    chartRef.current = chart

    chart.paddingRight = 20

    // Create X axis
    let xAxis = chart.xAxes.push(new am4charts.ValueAxis())
    xAxis.renderer.minGridDistance = 40
    xAxis.title.text = "East"
    xAxis.renderer.baseGrid.strokeOpacity = 0.5
    xAxis.renderer.baseGrid.strokeWidth = 1
    xAxis.strictMinMax = true

    // Create y axis
    let yAxis = chart.yAxes.push(new am4charts.ValueAxis())
    yAxis.renderer.minGridDistance = 40
    yAxis.title.text = "North"
    yAxis.renderer.baseGrid.strokeOpacity = 0.5
    yAxis.renderer.baseGrid.strokeWidth = 1
    yAxis.strictMinMax = true

    // Store axis refs for use in updateChartZoom
    xAxisRef.current = xAxis
    yAxisRef.current = yAxis

    // Robot Path series
    let pathSeries = chart.series.push(new am4charts.LineSeries())
    pathSeries.dataFields.valueX = "ax"
    pathSeries.dataFields.valueY = "ay"
    pathSeries.dataFields.value = "aValue"
    pathSeries.strokeWidth = 2
    pathSeriesRef.current = pathSeries

    let bullet1 = pathSeries.bullets.push(new am4charts.CircleBullet())
    bullet1.circle.radius = 3
    bullet1.tooltipText = "[bold]Index {value}[/] ({valueX}, {valueY})"

    // Robot Location series
    let robotSeries = chart.series.push(new am4charts.LineSeries())
    robotSeries.dataFields.valueX = "bx"
    robotSeries.dataFields.valueY = "by"
    robotSeries.strokeWidth = 2
    robotSeries.stroke = am4core.color("red")
    robotSeriesRef.current = robotSeries

    robotSeries.data = [{ bx: 0, by: 0, angle: 0 }]

    let bullet2 = robotSeries.bullets.push(new am4charts.Bullet())
    bullet2.propertyFields.rotation = "angle"

    let arrow = bullet2.createChild(am4core.Triangle)
    arrow.horizontalCenter = "middle"
    arrow.verticalCenter = "middle"
    arrow.direction = "top"
    arrow.width = 10
    arrow.height = 25
    arrow.fill = am4core.color("#ffffff00")
    arrow.strokeWidth = 3
    arrow.stroke = am4core.color("red")

    chart.numberFormatter.numberFormat = "#.##"

    // Vehicle Path Series
    let vehiclePathSeries = chart.series.push(new am4charts.LineSeries())
    vehiclePathSeriesRef.current = vehiclePathSeries
    vehiclePathSeries.dataFields.valueX = "cx"
    vehiclePathSeries.dataFields.valueY = "cy"
    vehiclePathSeries.dataFields.value = "cValue"
    vehiclePathSeries.strokeWidth = 2
    vehiclePathSeries.fill = am4core.color("orange")
    vehiclePathSeries.stroke = am4core.color("orange")
    let bullet3 = vehiclePathSeries.bullets.push(new am4charts.CircleBullet())
    bullet3.circle.radius = 3
    bullet3.tooltipText = "[bold]Index {value}[/] ({valueX}, {valueY})"
    vehiclePathSeries.hidden = !isVehiclePathVisible

    // Vehicle Location Series
    let vehiclePositionSeries = chart.series.push(new am4charts.LineSeries())
    vehiclePositionSeries.dataFields.valueX = "dx"
    vehiclePositionSeries.dataFields.valueY = "dy"
    vehiclePositionSeries.strokeWidth = 2
    vehiclePositionSeries.stroke = am4core.color("purple")
    vehiclePositionSeriesRef.current = vehiclePositionSeries

    // Initial data for vehiclePositionSeries
    vehiclePositionSeries.data = [{ dx: 0, dy: 0, veh_angle: 0 }]

    let bullet4 = vehiclePositionSeries.bullets.push(new am4charts.Bullet())
    bullet4.propertyFields.rotation = "veh_angle"

    let vehicleArrow = bullet4.createChild(am4core.Triangle)
    vehicleArrow.horizontalCenter = "middle"
    vehicleArrow.verticalCenter = "middle"
    vehicleArrow.direction = "top"
    vehicleArrow.width = 10
    vehicleArrow.height = 25
    vehicleArrow.fill = am4core.color("#ffffff00")
    vehicleArrow.strokeWidth = 3
    vehicleArrow.stroke = am4core.color("purple")
    vehicleArrow.visible = isVehiclePathVisible
    vehicleArrowRef.current = vehicleArrow

    const currentPathDisplay = pathDisplayRef.current;
    if (!currentPathDisplay) {
        console.error("PathDisplay instance not initialized in useLayoutEffect!");
        return;
    }

    // Initial plotting of paths.
    currentPathDisplay.plotPathSeries(
      networking.pathToFollow.latitudes,
      networking.pathToFollow.longitudes,
      pathSeriesRef,
      true // Force run to plot the initial path
    )

    currentPathDisplay.plotVehiclePathSeries(
      networking.vehiclePathToFollow.latitudes,
      networking.vehiclePathToFollow.longitudes,
      vehiclePathSeriesRef,
      true // Force run to plot the initial vehicle path
    )

    // IMPORTANT: Initial plot of robot/vehicle positions using current data
    currentPathDisplay.plotRobotSeries(
      networking.robotState.gps.latitude,
      networking.robotState.gps.longitude,
      networking.robotState.gps.heading,
      robotSeriesRef,
      true // Force update
    );

    currentPathDisplay.plotVehiclePositionSeries(
      networking.robotState.targetVehicle.latitude,
      networking.robotState.targetVehicle.longitude,
      networking.robotState.targetVehicle.heading,
      vehiclePositionSeriesRef,
      true // Force update for initial render
    );

    // Call initial zoom adjustment
    updateChartZoom()

    // Cleanup function: dispose of the chart when component unmounts
    return () => {
      chart.dispose()
    }
  }, [
    robotPathLatitudesStr,
    robotPathLongitudesStr,
    vehiclePathLatitudesStr,
    vehiclePathLongitudesStr,
    pathDisplayRef,
    networking,
    isVehiclePathVisible, 
    updateChartZoom 
  ])

  return (
    <div>
      <Button
        className={classes.button}
        variant="outlined"
        color="primary"
        onClick={() => {
          networking.senders.startPathFollowing()
        }}
      >
        start test
      </Button>

      <Button
        className={classes.button}
        variant="outlined"
        color="primary"
        onClick={() => {
          networking.senders.returnToStart()
        }}
      >
        return to start position
      </Button>

      <Button
        className={classes.button}
        variant="outlined"
        color="primary"
        onClick={() => {
          downloadTestData()
        }}
      >
        download test data
      </Button>

      {!isManualRecording && ( //If not manuall recording, start recording.
      <Button
          className={classes.button}
          variant="outlined"
          color="primary"
          onClick={handleStartManualRecording}
        >
          Start Manual Recording
        </Button>
      )}

      {isManualRecording && ( //If manual recording is going, stop recoring.
        <Button
          className={`${classes.button} ${classes.stopManualRecording}`}
          variant="contained"
          onClick={handleStopManualRecording}
        >
          Stop Manual Recording
        </Button>
      )}

      <Typography variant="body2" className={classes.body}>
        GPS status: {GNSS_FIX_TYPE[networking.robotState.gps.status]}
        <br />
        Robot Location: ({pathDisplayRef.current?.robot_east.toFixed(2) || "N/A"}, {pathDisplayRef.current?.robot_north.toFixed(2) || "N/A"})
        <br />
        Heading: {((networking.robotState.gps.heading / Math.PI) * 180).toFixed(0)} deg
        <br />
        Speed:{" "}
        {Math.sqrt(
          networking.robotState.gps.eastVelocity ** 2 + networking.robotState.gps.northVelocity ** 2
        ).toFixed(2)}{" "}
        m/s
      </Typography>

      {/* Checkbox for toggling vehicle path visibility */}
      <label>
        <input
          type="checkbox"
          checked={isVehiclePathVisible}
          onChange={toggleVehiclePathVisibility}
        />
        Show Vehicle
      </label>

      <div style={chartContainer}>
        <div id="chartdiv" style={chartStyle} />
      </div>

      <Typography variant="h6" style={{ marginTop: "15px" }}>
        Test Log
      </Typography>
      <Box
        mb={2}
        display="flex"
        flexDirection="column"
        height="250px"
        style={{
          border: "2px solid lightgrey",
          overflow: "hidden",
          overflowY: "scroll",
          overflowX: "scroll",
          padding: "10px",
        }}
      >
        {networking.testLogMessages.map((msg) => (
          <div key={msg}> {msg} </div>
        ))}
      </Box>
    </div>
  )
}
